    /// <summary>
    /// get document type
    /// </summary>
    /// <returns>List</returns>
    public List getDocumentTypes()
    {
        List ret = next getDocumentTypes();

        ret.addEnd(PrintMgmtDocumentType::METArrivalOverviewDockCopy);
        ret.addEnd(PrintMgmtDocumentType::METPOContinuingPermissionNote);

        return ret;
    }
